import type { Etf } from '@/data/etfs';
import type { Projection, Scenario } from '@/lib/calculations/project';
import { money } from '@/lib/format';
export function Results({funds,results,scenario,step="03"}:{funds:[Etf,Etf];results:[Projection,Projection];scenario:Scenario;step?:string|null}) {
 const difference=Math.abs(results[0].balance-results[1].balance);
 return <section className="results" aria-labelledby="results-title"><div className="section-label">{step&&<span className="step">{step}</span>}<h2 id="results-title">Stejná investice. Různé náklady.</h2></div><div className="result-highlight" aria-live="polite" aria-atomic="true"><p className="eyebrow">Modelový rozdíl za {scenario.years} let</p><p className="difference" data-testid="model-difference">{money(difference)}</p><p>Při stejném hrubém výnosu a vkladech. Nejde o garantovanou úsporu ani doporučení fondu.</p></div>
 <div className="result-pair">{results.map((result,i)=><div key={funds[i].id} className="result-fund"><span className="eyebrow">{funds[i].ticker}</span><p className="balance">{money(result.balance)}</p><span className="small">Modelový zůstatek</span><div className="balance-track" aria-hidden="true"><span style={{width:`${result.baseline>0?Math.max(0,Math.min(100,result.balance/result.baseline*100)):0}%`}}/></div><p className="cost-impact">Dopad nákladů <strong>{money(result.costImpact)}</strong></p></div>)}</div>
 <dl className="baseline"><div><dt>Celkem vloženo</dt><dd>{money(results[0].contributed)}</dd></div><div><dt>Bez průběžných nákladů</dt><dd>{money(results[0].baseline)}</dd></div></dl><p className="result-note">Dopad zahrnuje náklady i ušlé složené zhodnocení. Nezahrnuje daně, poplatky brokera, spread ani směnu měn. Kč jsou modelová jednotka, nikoliv měnová předpověď.</p><div className="result-sources">{funds.map(f=><a key={f.id} href={f.sourceUrl} target="_blank" rel="noopener noreferrer">{f.ticker} · zdroj emitenta ↗ <span>Načteno {f.retrievedAt}</span></a>)}</div></section>;
}
